from datetime import datetime, timedelta

# Get today's date
today = datetime.today()

# Calculate yesterday's date
yesterday = today - timedelta(days=1)

# Determine the day of the week for yesterday
yesterday_day_of_week = yesterday.strftime("%A").lower()

# Find the duration for the corresponding day
if yesterday_day_of_week == "monday":
    duration = 35
elif yesterday_day_of_week == "tuesday":
    duration = 65
elif yesterday_day_of_week == "wednesday":
    duration = 45
elif yesterday_day_of_week == "thursday":
    duration = 30
elif yesterday_day_of_week == "friday":
    duration = 55
elif yesterday_day_of_week == "saturday":
    duration = 130
elif yesterday_day_of_week == "sunday":
    duration = 0
else:
    duration = 0  # Default case if the day is not found

print(f"Workout duration for yesterday: {duration} minutes")

